import re

from django.db import migrations, models


IGNORED_WORDS = {"a", "an", "and", "for", "in", "of", "the", "to"}


def populate_program_codes(apps, schema_editor):
    Program = apps.get_model("course", "Program")
    database = schema_editor.connection.alias
    programs = Program.objects.using(database).order_by("pk")
    used_codes = set(
        programs.exclude(code__isnull=True)
        .exclude(code="")
        .values_list("code", flat=True)
    )

    for program in programs.filter(models.Q(code__isnull=True) | models.Q(code="")).iterator():
        words = re.findall(r"[A-Za-z0-9]+", program.title)
        significant_words = [
            word for word in words if word.casefold() not in IGNORED_WORDS
        ]
        if len(significant_words) == 1:
            base_code = significant_words[0][:5].upper()
        else:
            base_code = "".join(word[0] for word in significant_words).upper()[:20]
        base_code = base_code or "PROG"

        code = base_code
        suffix = 2
        while code in used_codes:
            suffix_text = str(suffix)
            code = f"{base_code[:20 - len(suffix_text)]}{suffix_text}"
            suffix += 1

        program.code = code
        program.save(using=database, update_fields=("code",))
        used_codes.add(code)


